# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#verify_data_column_sidecar
func verify_data_column_sidecar*(sidecar: fulu.DataColumnSidecar):
                                 Result[void, cstring] =
  ## Verify if the data column sidecar is valid.

  if sidecar.index >= NUMBER_OF_COLUMNS:
    return err("Data column sidecar index exceeds the NUMBER_OF_COLUMNS")

  if sidecar.kzg_commitments.len == 0:
    return err("Data column contains zero blob")

  if sidecar.column.len != sidecar.kzg_commitments.len or
      sidecar.column.len != sidecar.kzg_proofs.len:
    return err("Data column length must be equal to the number of commitments/proofs")

  ok()

# https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.3/specs/fulu/p2p-interface.md#verify_data_column_sidecar_inclusion_proof
func verify_data_column_sidecar_inclusion_proof*(sidecar: fulu.DataColumnSidecar):
                                                 Result[void, cstring] =
  ## Verify if the given KZG commitments included in the given beacon block.
  let gindex =
    KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH_GINDEX.GeneralizedIndex
  if not is_valid_merkle_branch(
      hash_tree_root(sidecar.kzg_commitments),
      sidecar.kzg_commitments_inclusion_proof,
      KZG_COMMITMENTS_INCLUSION_PROOF_DEPTH.int,
      get_subtree_index(gindex),
      sidecar.signed_block_header.message.body_root):

  peer_score = peer.getScore()
let columns = await dataColumnSidecarsByRoot(peer, DataColumnsByRootIdentifierList intColIdList)
if columns.isOk:
  var ucolumns = columns.get().asSeq()
  ucolumns.sort(cmpSidecarIndexes)
  let records = checkColumnResponse(colIdList, ucolumns).valueOr:
    debug "Response to columns by root is not a subset",
      peer = peer,
      columns = shortLog(colIdList),
      ucolumns = len(ucolumns)
    peer.updateScore(PeerScoreBadResponse)
    return
  for col in records:
    debug "Received column responses",
      peer = peer,
      column_sidecars = shortLog(col.sidecar[]),
      peer_score = peer.getScore()
    rman.dataColumnQuarantine[].put(col.block_root, col.sidecar)
  var curRoot: Eth2Digest
  for col in records:
    if col.block_root != curRoot:
      curRoot = col.block_root
      if (let o = rman.quarantine[].popColumnless(curRoot); o.isSome):
        let col = o.unsafeGet()
        discard await rman.blockVerifier(col, false)
else:
  debug "Data columns by root request failed or peer missing custody columns",
    peer = peer,
    err = columns.error()
  peer.updateScore(PeerScoreNoValues)

